-- Historique 2025 importe de Leaguepedia (https://lol.fandom.com, CC BY-SA 3.0) par
-- import/import_leaguepedia.py : NE PAS EDITER A LA MAIN, regenerer le fichier.
-- Structure des tournois (phases, poules, brackets relies) SANS les scores : les
-- resultats se saisissent dans l'appli, les playoffs avancent au fil des scores.

CREATE TEMP TABLE lp_team (lp_name TEXT PRIMARY KEY, team_id BIGINT NOT NULL);
CREATE TEMP TABLE lp_match (k TEXT PRIMARY KEY, match_id BIGINT NOT NULL);

-- Equipe actuelle (apres renommages) : existante de meme nom, ou de meme code si elle
-- existe encore aujourd'hui ; sinon creee (code rendu unique si deja pris).
CREATE FUNCTION pg_temp.lp_team(p_name TEXT, p_code TEXT, p_region TEXT, p_active BOOLEAN) RETURNS BIGINT AS $$
DECLARE v_id BIGINT; v_code TEXT := p_code; n INT := 1;
BEGIN
    SELECT id INTO v_id FROM team WHERE lower(name) = lower(p_name) ORDER BY id LIMIT 1;
    IF v_id IS NULL AND p_active THEN
        SELECT id INTO v_id FROM team WHERE code = p_code ORDER BY id LIMIT 1;
    END IF;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
    WHILE EXISTS (SELECT 1 FROM team WHERE code = v_code) LOOP
        n := n + 1;
        v_code := left(p_code, 18) || n;
    END LOOP;
    RETURN v_id;
END $$ LANGUAGE plpgsql;


